async function main() {
  console.log(`[expand-player-roles-2] Starting — ${PLAYERS.length} candidates`);
  const { data: existing } = await supabase.from("player_role_profiles").select("player_name, country");
  const seededKeys = new Set((existing ?? []).map((r: { player_name: string; country: string }) => `${r.player_name}|${r.country}`));
  const toInsert = PLAYERS.filter((p) => !seededKeys.has(`${p.player_name}|${p.country}`));
  if (!toInsert.length) { console.log("[expand-player-roles-2] All already seeded."); return; }
  console.log(`[expand-player-roles-2] Inserting ${toInsert.length} players (${seededKeys.size} already exist)`);
  for (let i = 0; i < toInsert.length; i += 50) {
    const batch = toInsert.slice(i, i + 50);
    const { error } = await supabase.from("player_role_profiles").insert(batch);
    if (error) { console.error(`Batch error at ${i}:`, error.message); process.exit(1); }
    console.log(`  Inserted batch ${Math.floor(i/50)+1} (${batch.length} rows)`);
  }
  console.log(`[expand-player-roles-2] Done — ${toInsert.length} players inserted`);
}
main().catch((e) => { console.error(e); process.exit(1); });
